import React from 'react';
import './Header.css'; // Import CSS file for styling
import avatar from "./avatar.png";
import { Avatar, Box, Grid, Stack, Typography } from '@mui/material';
import { useUser } from '../../Context/userContext';
import RatingBox from '../../Component/RatingBox';
import { useNavigate } from 'react-router-dom';
const Header = () => {


    const { user } = useUser();
    return (

    <Box
      className="header"
      sx={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        padding: 2,
        backgroundColor: '#1ab5caff', // สีพื้นหลังอ่อน ๆ
        borderRadius:5
      }}
    >
      {/* ฝั่งซ้าย: Avatar */}
      <Box sx={{ marginRight: 3 }}>
        <Avatar
          src={avatar}
          alt="avatar"
          sx={{ width: 100, height: 100 }}
        />
      </Box>

      {/* ฝั่งขวา: ข้อมูลสมาชิก */}
      <Stack spacing={1} sx={{ textAlign: 'left' }}>
        <RatingBox value={5} title="" />
        <Typography variant="body1" color='info' sx={{fontWeight:500}}>สวัสดี {user?.fullName}</Typography>
        <Typography color='info' sx={{fontWeight:500}}>ผ่อนไปใช้ไป เลือกผ่อนได้สบายๆ</Typography>
      </Stack>
    </Box>

    );
};

export default Header;
